/// <reference types="svelte" />
import { facade } from '@bus/facade';
import { GameEventType as Evt } from '../bus/events.js';
import type { AcademyCoursesSnapshot } from '../lib/academyCoursesSnapshot.ts';
import { buildAcademyCoursesSnapshot } from '../lib/academyCoursesSnapshot.ts';
import type { GameRuntime } from '../types/game.js';

const EMPTY: AcademyCoursesSnapshot = {
  language: 'fr',
  titleLabel: 'Cours de l\'Académie',
  creditsLabel: 'Crédits',
  rankLabel: 'Rang',
  investLabel: 'Investir',
  lockedLabel: 'Verrouillé',
  courses: [],
};

class AcademyStore {
  snapshot: AcademyCoursesSnapshot = $state(EMPTY);
}

export const academy = new AcademyStore();

facade.subscribe(Evt.ACADEMY_COURSES_CHANGED, () => {
  const game = (globalThis as { game?: GameRuntime }).game ?? null;
  if (!game) return;
  academy.snapshot = buildAcademyCoursesSnapshot(game);
});
